vec3 sphere_centre = vec3(0);
float sphere_radius = 0.4;

vec2 sphere_line_intersection(in vec3 centre, in float radius, in vec3 ray_origin, in vec3 ray_direction) {
    float dir_sqr = dot(ray_direction, ray_direction);
    float diff = dot(ray_direction, centre - ray_origin);
    float sum = dot(ray_origin, ray_origin) + dot(centre, centre) - radius * radius;
    float discr_sqrt = sqrt(diff * diff - dir_sqr * sum);

    return vec2(
        diff + discr_sqrt,
        diff - discr_sqrt
    ) / dir_sqr;
}

vec3 get_sphere_normal(in vec3 centre, in vec3 position) {
    return normalize(position - centre);
}

vec3 calculate_density(in vec3 centre, in vec3 position, in float radius, in vec3 density_falloff) {
    float initial_density = 1.0;

    float dist = length(centre - position);
    return initial_density * (exp(-dist / density_falloff) - exp(-radius / density_falloff));
}

vec3 calculate_volume(in vec3 ray_origin, in vec3 ray_direction, in float max_dist, in vec3 light_pos) {
    int   MAX_STEPS = 5000 / 26;
    float STEP_SIZE = 0.006;
    vec3  EPS_GAS_VOLUME = vec3(1) / 10000.0;
    vec3  PLANET_CENTRE = vec3(0);
    float ATMOSPHERE_RADIUS = 0.65;
    vec3  DISTANCE_MULTIPLIER = vec3(260, 220, 280) * 3000000.0;

    vec3 gas_volume = vec3(0.0);
    float dist = 0.0;
    for (int i = 0; i < MAX_STEPS; ++i) {
        vec3 position = ray_origin + dist * ray_direction;
        vec3 to_light_dir = normalize(light_pos - position);
        to_light_dir.z *= -1.0;
        vec2 t = sphere_line_intersection(sphere_centre, sphere_radius, position, to_light_dir);

        vec3 density = max(calculate_density(
            PLANET_CENTRE,
            position,
            ATMOSPHERE_RADIUS,
            vec3(1, 1.07, 1.13) * 0.1
        ), vec3(0));

        vec3 volume = STEP_SIZE * EPS_GAS_VOLUME * density;

        if (dist > max_dist - STEP_SIZE)
            break;

        dist += STEP_SIZE;

        if (t.x < 1000.0 && 0.0 < t.x)
            continue;

        float light_dist = length(light_pos - position);
        gas_volume += volume / exp(light_dist * 2.0) * DISTANCE_MULTIPLIER;
    }

    return gas_volume;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float ambient_brightness = 0.2;
    float specular_power = 20.0;
    float specular_multiplier = 0.4;
    float gas_color_density = 18000.0;
    float diffusion_intensity = 40.0;

    vec2 uv = 2.0 * fragCoord / iResolution.xy - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 ray_origin = vec3(0, 0, -1);
    vec3 ray_direction = normalize(vec3(uv, 0) - ray_origin);

    vec2 t = sphere_line_intersection(sphere_centre, sphere_radius, ray_origin, ray_direction);
    vec3 nearest_hit_pos = ray_origin + t.x * ray_direction;

    vec3 light_pos = 6.0 * vec3(cos(2.0 * iTime), 1, sin(2.0 * iTime));
    vec3 dir_to_light = normalize(light_pos - nearest_hit_pos);

    vec3 gas_volume = calculate_volume(ray_origin, ray_direction, t.x, light_pos);

    vec3 normal = get_sphere_normal(sphere_centre, nearest_hit_pos);
    float light_dist = length(nearest_hit_pos - light_pos);
    float brightness = diffusion_intensity * max(ambient_brightness, dot(normal, dir_to_light))
                     / (light_dist * light_dist);

    vec3 reflected = reflect(-ray_direction, normal);
    float r_dot_l = max(0.0, dot(dir_to_light, reflected));
    float specular_brightness = pow(r_dot_l, specular_power) * specular_multiplier;

    vec3 color = normal * 0.5 + 0.5;
    color *= brightness;
    color += specular_brightness;

    color = clamp(color, 0.0, 1.0);

    vec3 gas_color = gas_volume * gas_color_density;

    fragColor = vec4(gas_color + color, 1);
}
